function load(n){for(const p of [file(n),path.join(DATA,`${n}.json`),...(n==='economy'?[path.join(ROOT,'ekonomia.json'),path.join(DATA,'ekonomia.json')]:[])]){if(fs.existsSync(p))try{return JSON.parse(fs.readFileSync(p,'utf8'))}catch(e){console.error('JSON',p,e.message)}}return{}}
function db(n){if(!cache.has(n)){const d=merge(load(n),defaults[n]||{});cache.set(n,d);try{fs.writeFileSync(file(n),JSON.stringify(d,null,2))}catch(e){console.error(e)}}return cache.get(n)}
function save(n){const p=file(n),t=p+'.tmp';fs.writeFileSync(t,JSON.stringify(db(n),null,2));fs.renameSync(t,p)}
