reg(cmd('regulamin-panel','Wyślij regulamin'),async i=>{if(!admin(i))return no(i,'Brak uprawnień.');const c=db('regulamin-config'),t=i.guild.channels.cache.get(c.channelId)||i.channel;if(!t?.isTextBased())return no(i,'Zły kanał.');let m=c.messageId?await t.messages.fetch(c.messageId).catch(()=>null):null;m?await m.edit(rules(i.guild)):m=await t.send(rules(i.guild));c.channelId=t.id;c.messageId=m.id;save('regulamin-config');return ok(i,'Regulamin wysłany/zaktualizowany.')});

