function radioState(gid){const r=radioRuntime.get(gid);if(!r?.running)return'offline';return r.player?.state?.status===AudioPlayerStatus.Playing?'online':'limited'}
function destroyRadio(gid){const r=radioRuntime.get(gid);if(!r)return;r.running=false;try{r.player?.stop(true)}catch{}try{r.connection?.destroy()}catch{}radioRuntime.delete(gid)}
async function spotifyToTracks(url,customName){if(/\/track\//i.test(url)){const x=await getSpotifyPreview(url);return[{name:customName||[x.artist,x.title||x.track].filter(Boolean).join(' - ')||'Spotify',url,provider:'spotify'}]}const arr=await getSpotifyTracks(url);return(arr||[]).map((x,j)=>{const artists=Array.isArray(x.artists)?x.artists.map(a=>typeof a==='string'?a:a?.name).filter(Boolean).join(', '):(x.artist||'');const title=x.name||x.title||`Utwór ${j+1}`;return{name:customName&&arr.length===1?customName:[artists,title].filter(Boolean).join(' - '),url:x.external_urls?.spotify||x.url||url,provider:'spotify',query:[artists,title].filter(Boolean).join(' ')}})}
async function expandRadioUrl(url,customName){url=String(url||'').trim();if(!/^https?:\/\//i.test(url))throw new Error('Podaj poprawny link http/https.');if(/open\.spotify\.com/i.test(url))return spotifyToTracks(url,customName);if(/(?:youtube\.com|youtu\.be)/i.test(url)){if(/[?&]list=/.test(url)){const pl=await play.playlist_info(url,{incomplete:true});const vids=await pl.all_videos();if(vids?.length)return vids.map(v=>({name:v.title||customName||'YouTube',url:v.url,provider:'youtube'}))}const info=await play.video_basic_info(url);return[{name:customName||info.video_details?.title||'YouTube',url,provider:'youtube'}]}return[{name:customName||'Stream',url,provider:'direct'}]}
async function resolveRadioTrack(track){if(track.provider==='spotify'||/open\.spotify\.com/i.test(track.url)){let query=track.query;if(!query){const x=await getSpotifyPreview(track.url);query=[x.artist,x.title||x.track].filter(Boolean).join(' ')}const results=await play.search(`${query} audio`,{limit:5,source:{youtube:'video'}});if(!results.length)throw new Error(`Nie znaleziono źródła dla: ${track.name}`);return{name:track.name||results[0].title,url:results[0].url,provider:'youtube'}}return track}
async function makeRadioResource(track){const r=await resolveRadioTrack(track);if(r.provider==='youtube'||/(?:youtube\.com|youtu\.be)/i.test(r.url)){const st=await play.stream(r.url,{discordPlayerCompatibility:true});return{resource:createAudioResource(st.stream,{inputType:st.type,inlineVolume:true,metadata:r}),resolved:r}}return{resource:createAudioResource(r.url,{inlineVolume:true,metadata:r}),resolved:r}}
async function playRadioNext(guild){const c=db('radio-config'),r=radioRuntime.get(guild.id);if(!r?.running)return;const list=radioList(r.station);if(!list.length){r.now=null;r.problem='Pusta playlista';await refreshStatus(guild).catch(()=>{});setTimeout(()=>{if(r.running)playRadioNext(guild).catch(console.error)},15000);return}c.lastIndex??={halloween:0,christmas:0,general:0};let idx=Number(c.lastIndex[r.station]||0);if(!Number.isFinite(idx)||idx<0)idx=0;idx%=list.length;const track=list[idx];c.lastIndex[r.station]=(idx+1)%list.length;save('radio-config');try{const{resource,resolved}=await makeRadioResource(track);if(resource.volume)resource.volume.setVolume(Math.max(0,Math.min(2,Number(c.volume||35)/100)));r.now=resolved;r.problem=null;r.player.play(resource);await refreshStatus(guild).catch(()=>{})}catch(e){console.error('Radio utwór:',e);r.problem=e.message;setTimeout(()=>{if(r.running)playRadioNext(guild).catch(console.error)},2500)}}
async function startRadio(guild,station,fromWatchdog=false){const c=db('radio-config');station=station||c.station;if(!RADIO_META[station])throw new Error('Nieprawidłowa stacja.');const ch=guild.channels.cache.get(c.channelId);if(!ch||ch.type!==ChannelType.GuildVoice)throw new Error('Ustaw kanał głosowy przez /radio-config kanal.');if(!radioList(station).length)throw new Error(`Playlista ${RADIO_META[station].label} jest pusta. Dodaj link przez /radio dodaj.`);destroyRadio(guild.id);const player=createAudioPlayer({behaviors:{noSubscriber:NoSubscriberBehavior.Play}}),connection=joinVoiceChannel({channelId:ch.id,guildId:guild.id,adapterCreator:guild.voiceAdapterCreator,selfDeaf:true,selfMute:false}),r={connection,player,running:true,station,now:null,problem:null,reconnecting:false};radioRuntime.set(guild.id,r);connection.subscribe(player);player.on(AudioPlayerStatus.Idle,()=>{if(r.running)playRadioNext(guild).catch(console.error)});player.on('error',e=>{console.error('Radio player:',e);r.problem=e.message;if(r.running)setTimeout(()=>playRadioNext(guild).catch(console.error),2000)});connection.on(VoiceConnectionStatus.Disconnected,async()=>{if(!r.running||r.reconnecting)return;r.reconnecting=true;try{await Promise.race([entersState(connection,VoiceConnectionStatus.Signalling,5000),entersState(connection,VoiceConnectionStatus.Connecting,5000)]);r.reconnecting=false}catch{try{connection.destroy()}catch{}radioRuntime.delete(guild.id);const cfg=db('radio-config');if(cfg.enabled)setTimeout(()=>startRadio(guild,cfg.station,true).catch(e=>console.error('Radio reconnect:',e.message)),5000)}});connection.on(VoiceConnectionStatus.Ready,()=>{r.reconnecting=false;r.problem=null});c.station=station;c.enabled=true;save('radio-config');await playRadioNext(guild);if(!fromWatchdog)await refreshStatus(guild).catch(()=>{});return r}
function radioEmbed(g){const c=db('radio-config'),r=radioRuntime.get(g.id),st=RADIO_META[r?.station||c.station]||RADIO_META.general;return new EmbedBuilder().setColor(r?.running?0x57F287:0x2B2D31).setTitle('📻 VEYRO • RADIO 24/7').setDescription(`${r?.running?'🟢 **Nadaje 24/7**':'⚫ **Wyłączone**'}\n\n**Stacja:** ${st.emoji} ${st.label}\n**Kanał:** ${c.channelId?`<#${c.channelId}>`:'Brak'}\n**Teraz:** ${r?.now?`**${r.now.name}**`:'—'}\n**Głośność:** **${c.volume}%**\n**Po wyjściu użytkowników:** **gra dalej**\n**Po restarcie bota:** **${c.enabled?'wraca automatycznie':'wyłączone'}**${r?.problem?`\n\n⚠️ ${cut(r.problem,500)}`:''}`).setFooter({text:`${g.name} • Radio 24/7`}).setTimestamp()}
