reg(radioCmd,async i=>{const a=i.options.getSubcommand(),c=db('radio-config');if(a==='teraz')return i.reply({embeds:[radioEmbed(i.guild)]});if(a==='lista'){const st=S(i,'stacja'),list=radioList(st),meta=RADIO_META[st];return i.reply({embeds:[emb(`📻 ${meta.emoji} ${meta.label}`,list.length?list.slice(0,50).map((x,j)=>`**${j+1}.** ${cut(x.name,80)} — ${x.provider||'link'}`).join('\n'):'Playlista jest pusta.')],flags:MessageFlags.Ephemeral})}if(!admin(i))return no(i,'Brak uprawnień.');if(a==='graj'){await i.deferReply({flags:MessageFlags.Ephemeral});try{const st=S(i,'stacja');await startRadio(i.guild,st);return i.editReply({embeds:[emb('📻 Radio 24/7',`Uruchomiono **${RADIO_META[st].emoji} ${RADIO_META[st].label}**. Bot będzie grał nawet gdy wszyscy wyjdą z kanału.`,0x57F287)]})}catch(e){return i.editReply({embeds:[emb('❌ Radio',e.message,0xED4245)]})}}if(a==='stop'){c.enabled=false;save('radio-config');destroyRadio(i.guild.id);await refreshStatus(i.guild).catch(()=>{});return ok(i,'Radio zatrzymane.')}if(a==='pomin'){const r=radioRuntime.get(i.guild.id);if(!r?.running)return no(i,'Radio nie gra.');r.player.stop(true);return ok(i,'Pominięto utwór.')}if(a==='dodaj'){await i.deferReply({flags:MessageFlags.Ephemeral});try{const st=S(i,'stacja'),url=S(i,'url'),name=S(i,'nazwa'),items=await expandRadioUrl(url,name);if(!items.length)throw new Error('Nie znaleziono utworów pod tym linkiem.');radioList(st).push(...items);save('radio-config');return i.editReply({embeds:[emb('✅ Dodano do radia',`Stacja: **${RADIO_META[st].emoji} ${RADIO_META[st].label}**\nDodano pozycji: **${items.length}**`,0x57F287)]})}catch(e){return i.editReply({embeds:[emb('❌ Nie udało się dodać',cut(e.message,1500),0xED4245)]})}}if(a==='usun'){const st=S(i,'stacja'),list=radioList(st),n=N(i,'numer')-1;if(n<0||n>=list.length)return no(i,'Nie ma takiego numeru.');const[x]=list.splice(n,1);save('radio-config');return ok(i,`Usunięto **${x.name}**.`)}});
