const SM={online:['Online','🟢',0x57F287],limited:['Ograniczone działanie','🟡',0xFEE75C],maintenance:['Prace techniczne','🟠',0xF47B20],update:['Aktualizacja','🔵',0x3498DB],degraded:['Zakłócenia','⚠️',0xF1C40F],unavailable:['Niedostępne','🔴',0xED4245],offline:['Offline','⚫',0x2B2D31]},SC=Object.entries(SM).map(([value,[name,emoji]])=>({name:`${emoji} ${name}`,value}));
const STATUS_BASE=[{id:'4fun',name:'4Fun',emoji:'🎲'},{id:'ekonomia',name:'Ekonomia',emoji:'💰'},{id:'lvl',name:'Level',emoji:'⭐'},{id:'automod',name:'AutoModeracja',emoji:'🛡️'},{id:'autokanal',name:'AutoKanał',emoji:'🔊'},{id:'tickety',name:'Tickety',emoji:'🎫'},{id:'rekrutacja',name:'Rekrutacja',emoji:'📝'},{id:'sugestie',name:'Sugestie',emoji:'💡'},{id:'partnerstwa',name:'Partnerstwa',emoji:'🤝'},{id:'powitania',name:'Powitania',emoji:'👋'},{id:'moderacja',name:'Moderacja',emoji:'⚙️'},{id:'apelacje',name:'Apelacje',emoji:'📨'},{id:'changelog',name:'Changelog',emoji:'📰'},{id:'radio',name:'Radio 24/7',emoji:'📻'}];
function migrateStatusPanel(){const c=db('status-panel-config'),old=Array.isArray(c.sections)?c.sections:[];const expected=STATUS_BASE.map(x=>x.id).join('|'),current=old.map(x=>x.id).filter(Boolean).join('|');if(c.schemaVersion===3&&current===expected)return;c.sections=STATUS_BASE.map(base=>{const prev=old.find(x=>x.id===base.id||String(x.name||'').toLowerCase()===base.name.toLowerCase());return{...base,status:prev?.status&&SM[prev.status]?prev.status:(base.id==='radio'?'offline':'online')}});c.schemaVersion=3;save('status-panel-config')}
function statE(g){const c=db('status-panel-config'),m=SM[c.state]||SM.online,r=radioRuntime.get(g.id),sc=db('status-config');const e=new EmbedBuilder().setColor(m[2]).setAuthor({name:`${g.name} • Status usług`,iconURL:g.iconURL({size:256})||undefined}).setTitle(`📡 ${g.name.toUpperCase()} • STATUS SYSTEMÓW`).setDescription(`### ${m[1]} ${m[0]}\n> ${c.description}\n\n**Legenda:** 🟢 Online • 🟡 Ograniczone • 🟠 Prace • 🔵 Aktualizacja • ⚠️ Zakłócenia • 🔴 Niedostępne • ⚫ Offline`).setThumbnail(g.iconURL({size:512})||null);for(const sec of c.sections||[]){const state=sec.id==='radio'?radioState(g.id):sec.status,x=SM[state]||SM.online;let value=`${x[1]} **${x[0]}**`;if(sec.id==='radio'&&r?.running){const meta=RADIO_META[r.station]||RADIO_META.general;value+=`\n${meta.emoji} ${meta.label}${r.now?.name?`\n🎵 ${cut(r.now.name,70)}`:''}`}e.addFields({name:`${sec.emoji||'⚙️'} ${sec.name}`,value,inline:true})}const typeLabel={Playing:'Gra w',Watching:'Ogląda',Listening:'Słucha',Competing:'Rywalizuje'}[sc.type]||sc.type,stateLabel={online:'Online',idle:'Zaraz wracam',dnd:'Nie przeszkadzać',invisible:'Niewidoczny'}[sc.state]||sc.state;e.addFields({name:'━━━━━━━━━━━━━━━━━━',value:'**Dane techniczne Veyro**',inline:false},{name:'📶 Ping',value:`**${Math.max(0,Math.round(client.ws.ping))} ms**`,inline:true},{name:'⏱️ Uptime',value:`**${fd(client.uptime||0)}**`,inline:true},{name:'🌐 Serwery',value:`**${client.guilds.cache.size}**`,inline:true},{name:'🤖 Obecność bota',value:`**${stateLabel}** • ${typeLabel} **${cut(sc.text,70)}**`,inline:false},{name:'🧩 Wersja',value:`**v${db('panel-config').version||BOT_VERSION}**`,inline:true},{name:'🕒 Ostatnia aktualizacja',value:`<t:${Math.floor(Date.now()/1000)}:R>`,inline:false});return e.setFooter({text:`© ${new Date().getFullYear()} ${g.name} • Veyro Status`}).setTimestamp()}
async function refreshStatus(g){const c=db('status-panel-config');if(!c.channelId||!c.messageId)return;const t=g.channels.cache.get(c.channelId);if(!t?.isTextBased())return;const m=await t.messages.fetch(c.messageId).catch(()=>null);if(m)await m.edit({embeds:[statE(g)]}).catch(()=>{})}
