const AUTOMOD_FILTERS={links:'🔗 Linki',invites:'📨 Zaproszenia Discord',spam:'🚨 Spam',duplicates:'📋 Powtórzenia',caps:'🔠 CAPS',mentions:'📣 Wzmianki',badwords:'🤬 Niedozwolone słowa'};
