 if(a==='rola-ignoruj-dodaj'){const r=i.options.getRole('rola');if(!c.ignoredRoles.includes(r.id))c.ignoredRoles.push(r.id);save('automod-config');return ok(i,`AutoMod będzie ignorował rolę ${r}.`)}
