 if(a==='slowo-dodaj'){const word=S(i,'tekst').trim().toLowerCase();if(!c.badWords.includes(word))c.badWords.push(word);save('automod-config');return ok(i,`Dodano: **${word}**`)}
 if(a==='slowo-usun'){const word=S(i,'tekst').trim().toLowerCase();c.badWords=c.badWords.filter(x=>x!==word);save('automod-config');return ok(i,`Usunięto: **${word}**`)}
 if(a==='domena-dodaj'){const domain=S(i,'domena').trim().toLowerCase().replace(/^https?:\/\//,'').replace(/^www\./,'').split('/')[0];if(!c.allowedDomains.includes(domain))c.allowedDomains.push(domain);save('automod-config');return ok(i,`Dozwolono domenę **${domain}**.`)}
 if(a==='domena-usun'){const domain=S(i,'domena').trim().toLowerCase().replace(/^https?:\/\//,'').replace(/^www\./,'').split('/')[0];c.allowedDomains=c.allowedDomains.filter(x=>x!==domain);save('automod-config');return ok(i,`Usunięto domenę **${domain}** z wyjątków.`)}
 if(a==='caps'){c.settings.caps.percentage=N(i,'procent');c.settings.caps.minLetters=N(i,'minimum');save('automod-config');return ok(i,`CAPS: **${c.settings.caps.percentage}%**, minimum **${c.settings.caps.minLetters} liter**.`)}
