const hist=new Map();
function getUrls(text){return String(text||'').match(/https?:\/\/[^\s<>()]+/gi)||[]}
function getDomain(url){try{return new URL(url).hostname.toLowerCase().replace(/^www\./,'')}catch{return null}}
function domainAllowed(domain,list){if(!domain)return false;return(list||[]).some(allowed=>domain===allowed||domain.endsWith(`.${allowed}`))}
async function automod(m){
 const c=ensureAutomod(db('automod-config'));
 if(!c.enabled||!m.guild||m.author.bot)return false;
 if(m.member?.permissions.has(PermissionsBitField.Flags.ManageMessages)||automodRoleIgnored(c,m.member))return false;
 const text=m.content||'',lower=text.toLowerCase();let violation=null;
 if(!violation&&c.invites&&!automodIgnored(c,'invites',m.channelId)&&/(discord\.gg\/|discord(?:app)?\.com\/invite\/)/i.test(text))violation='Zaproszenie Discord';
 if(!violation&&c.links&&!automodIgnored(c,'links',m.channelId)){const urls=getUrls(text);if(urls.length&&urls.some(url=>!domainAllowed(getDomain(url),c.allowedDomains)))violation='Niedozwolony link'}
 if(!violation&&c.badWordsEnabled!==false&&!automodIgnored(c,'badwords',m.channelId)&&(c.badWords||[]).some(word=>word&&lower.includes(word.toLowerCase())))violation='Niedozwolone słowo';
 const key=`${m.guild.id}:${m.author.id}`,now=Date.now(),maxWindow=Math.max(Number(c.settings.spam.seconds||10),Number(c.settings.duplicates.seconds||15))*1000;let history=(hist.get(key)||[]).filter(x=>now-x.time<maxWindow);history.push({text,time:now});hist.set(key,history);
 if(!violation&&c.spam&&!automodIgnored(c,'spam',m.channelId)){const window=Number(c.settings.spam.seconds||10)*1000,amount=history.filter(x=>now-x.time<=window).length;if(amount>=Number(c.settings.spam.messages||7))violation='Spam'}
 if(!violation&&c.duplicates&&!automodIgnored(c,'duplicates',m.channelId)){const window=Number(c.settings.duplicates.seconds||15)*1000,same=history.filter(x=>now-x.time<=window&&x.text.trim().toLowerCase()===text.trim().toLowerCase()).length;if(text.trim().length>=2&&same>=Number(c.settings.duplicates.messages||4))violation='Powtarzanie wiadomości'}
 if(!violation&&c.caps&&!automodIgnored(c,'caps',m.channelId)){const letters=text.replace(/[^a-ząćęłńóśźż]/gi,'');if(letters.length>=Number(c.settings.caps.minLetters||12)){const upper=letters.replace(/[^A-ZĄĆĘŁŃÓŚŹŻ]/g,'').length,percent=upper/letters.length*100;if(percent>=Number(c.settings.caps.percentage||75))violation=`CAPS (${Math.round(percent)}%)`}}
 if(!violation&&c.mentions&&!automodIgnored(c,'mentions',m.channelId)){const mentions=m.mentions.users.size+m.mentions.roles.size;if(mentions>Number(c.settings.mentions.max||6))violation=`Za dużo wzmianek (${mentions})`}
 if(!violation)return false;
 await m.delete().catch(()=>{});
 const warning=await m.channel.send({embeds:[new EmbedBuilder().setColor(0xED4245).setAuthor({name:'Veyro • AutoModeracja',iconURL:client.user.displayAvatarURL()}).setTitle('🛡️ Wiadomość została zatrzymana').setDescription(`${m.author}, Twoja wiadomość została usunięta przez AutoModerację.`).addFields({name:'📋 Powód',value:`**${violation}**`}).setFooter({text:'Veyro • Dbamy o porządek na serwerze'}).setTimestamp()]}).catch(()=>null);
 if(warning)setTimeout(()=>warning.delete().catch(()=>{}),6000);
 await log(m.guild,'moderation',new EmbedBuilder().setColor(0xED4245).setTitle('🛡️ AutoModeracja').addFields({name:'👤 Użytkownik',value:`${m.author}\n\`${m.author.id}\``,inline:true},{name:'💬 Kanał',value:`${m.channel}`,inline:true},{name:'📋 Powód',value:violation},{name:'📝 Wiadomość',value:cut(text||'Brak',1000)}).setTimestamp());
 return true;
}

group('logi-config','Konfiguracja logów',[['ustaw','Ustaw kanał',o=>o.addStringOption(x=>x.setName('typ').setDescription('Typ').setRequired(true).addChoices({name:'Domyślne',value:'default'},{name:'Wiadomości',value:'messages'},{name:'Członkowie',value:'members'},{name:'Moderacja',value:'moderation'},{name:'Voice',value:'voice'},{name:'Kanały',value:'channels'},{name:'Role',value:'roles'},{name:'Tickety',value:'tickets'})).addChannelOption(x=>x.setName('kanal').setDescription('Kanał').setRequired(true))],['pokaz','Pokaż konfigurację']],async i=>{if(!admin(i))return no(i,'Brak uprawnień.');const c=db('logi-config'),a=i.options.getSubcommand();if(a==='ustaw'){c[S(i,'typ')]=C(i,'kanal').id;save('logi-config');return ok(i,'Ustawiono.')}return i.reply({embeds:[emb('📋 Logi',Object.entries(c).map(([k,v])=>`**${k}:** ${v?`<#${v}>`:'—'}`).join('\n'))],flags:MessageFlags.Ephemeral})});
group('autokanal-config','Konfiguracja autokanału',[['wlacz','Włącz'],['wylacz','Wyłącz'],['tworzenie','Kanał tworzący',o=>chan(o,'kanal','Kanał')],['kategoria','Kategoria',o=>chan(o,'kanal','Kategoria')],['nazwa','Nazwa',o=>txt(o,'tekst','Kanał {user}')],['limit','Limit',o=>o.addIntegerOption(x=>x.setName('ilosc').setDescription('0-99').setRequired(true).setMinValue(0).setMaxValue(99))],['pokaz','Pokaż']],async i=>{if(!admin(i))return no(i,'Brak uprawnień.');const c=db('autokanal-config'),a=i.options.getSubcommand();if(a==='wlacz')c.enabled=true;if(a==='wylacz')c.enabled=false;if(a==='tworzenie')c.creatorId=C(i,'kanal').id;if(a==='kategoria')c.categoryId=C(i,'kanal').id;if(a==='nazwa')c.name=S(i,'tekst');if(a==='limit')c.limit=N(i,'ilosc');save('autokanal-config');if(a==='pokaz')return i.reply({embeds:[emb('🔊 Autokanał',`Status: **${c.enabled?'Włączony':'Wyłączony'}**\nKanał: ${c.creatorId?`<#${c.creatorId}>`:'Brak'}\nNazwa: **${c.name}**`)],flags:MessageFlags.Ephemeral});return ok(i,'Zapisano.')});
async function voice(oldS,newS){const c=db('autokanal-config');if(c.enabled&&newS.channelId===c.creatorId&&oldS.channelId!==c.creatorId){const x=await newS.guild.channels.create({name:c.name.replaceAll('{user}',newS.member.displayName),type:ChannelType.GuildVoice,parent:c.categoryId||undefined,userLimit:c.limit||0,permissionOverwrites:[{id:newS.member.id,allow:[PermissionsBitField.Flags.ManageChannels,PermissionsBitField.Flags.MoveMembers]}]});c.tempChannels.push(x.id);save('autokanal-config');await newS.setChannel(x).catch(()=>{})}if(oldS.channelId&&c.tempChannels.includes(oldS.channelId)){const x=oldS.guild.channels.cache.get(oldS.channelId);if(!x||x.members.size===0){await x?.delete().catch(()=>{});c.tempChannels=c.tempChannels.filter(y=>y!==oldS.channelId);save('autokanal-config')}}}
