const HALLOWEEN_END=new Date('2026-11-08T23:59:59+01:00').getTime(),eventOn=()=>Date.now()<=HALLOWEEN_END;
function wallet(g,u){const d=db('economy'),k=`${g}:${u}`;d[k]??={};const w=d[k];if(w.balance==null)w.balance=Number(w.candies||0);delete w.candies;w.inventory??={};w.cooldowns??={};save('economy');return w}function earn(g,u,k,cd,min,max){const w=wallet(g,u),now=Date.now(),until=w.cooldowns[k]||0;if(until>now)return{wait:until};const a=min+Math.floor(Math.random()*(max-min+1));w.balance+=a;w.cooldowns[k]=now+cd;save('economy');return{amount:a}}
group('ekonomia','Ekonomia',[['portfel','Pokaż portfel',o=>usr(o,'osoba','Użytkownik',false)],['codzienna','Nagroda dzienna'],['praca','Pracuj'],['ranking','Ranking']],async i=>{const a=i.options.getSubcommand(),cur=eventOn()?'🍬':'🪙';if(a==='portfel'){const u=U(i,'osoba')||i.user;return i.reply({embeds:[emb(`💰 Portfel • ${u.username}`,`Saldo: **${wallet(i.guild.id,u.id).balance} ${cur}**`)]})}if(a==='codzienna'||a==='praca'){const r=earn(i.guild.id,i.user.id,a,a==='codzienna'?86400000:1800000,a==='codzienna'?150:30,a==='codzienna'?300:90);if(r.wait)return no(i,`Spróbuj ponownie ${ts(r.wait)}.`);return ok(i,`Zdobyto **${r.amount} ${cur}**.`)}const arr=Object.entries(db('economy')).filter(([k])=>k.startsWith(`${i.guild.id}:`)).sort(([,a],[,b])=>(b.balance||0)-(a.balance||0)).slice(0,10);return i.reply({embeds:[emb('🏆 Ranking ekonomii',arr.length?arr.map(([k,d],j)=>`**${j+1}.** <@${k.split(':')[1]}> — **${d.balance||0} ${cur}**`).join('\n'):'Brak danych.')]})});
