// ===== INTERACTIONS =====
client.on('interactionCreate',async i=>{try{
 if(i.isAutocomplete()){
  const focused=i.options.getFocused(true);
  if(i.commandName==='status-panel-config'&&focused.name==='sekcja'){const c=db('status-panel-config'),q=String(focused.value||'').toLowerCase();return i.respond((c.sections||[]).filter(s=>s.name.toLowerCase().includes(q)||s.id.toLowerCase().includes(q)).slice(0,25).map(s=>({name:`${s.emoji||'⚙️'} ${s.name}`,value:s.id})))}
  if(i.commandName==='permisje-config'&&focused.name==='komenda'){const q=String(focused.value||'').toLowerCase();return i.respond(commands.map(c=>c.name).filter(n=>n.includes(q)).slice(0,25).map(n=>({name:`/${n}`,value:n})))}
  return i.respond([]);
 }
 if(i.isChatInputCommand()){if(!i.inGuild())return no(i,'Komendy tylko na serwerze.');if(!canUseCommand(i))return no(i,'Nie masz permisji do tej komendy albo nie można jej używać na tym kanale.');const h=handlers[i.commandName];if(h)await h(i);return}if(i.isStringSelectMenu()&&i.customId==='ticket:open'){await ticketAct(i);return}if(i.isStringSelectMenu()&&i.customId==='roles:select'){const c=db('role-config'),managed=c.roles.map(x=>x.roleId),sel=i.values.filter(x=>x!=='none'),added=[],removed=[],failed=[];for(const rid of managed){const r=i.guild.roles.cache.get(rid);if(!r)continue;const has=i.member.roles.cache.has(rid),want=sel.includes(rid);try{if(want&&!has){if(!r.editable)throw 0;await i.member.roles.add(r);added.push(r.name)}if(!want&&has){if(!r.editable)throw 0;await i.member.roles.remove(r);removed.push(r.name)}}catch{failed.push(r.name)}}return i.reply({embeds:[emb('🎭 Role zaktualizowane',`${added.length?`Dodano: **${added.join(', ')}**\n`:''}${removed.length?`Usunięto: **${removed.join(', ')}**\n`:''}${failed.length?`Nie udało się: **${failed.join(', ')}**`:''}${!added.length&&!removed.length&&!failed.length?'Brak zmian.':''}`)],flags:MessageFlags.Ephemeral})}if(i.isButton()){if(i.customId==='rules:accept'){const c=db('regulamin-config'),r=i.guild.roles.cache.get(c.verifiedRoleId);if(!c.verificationEnabled||!r?.editable)return no(i,'Akceptacja wyłączona lub rola niedostępna.');if(i.member.roles.cache.has(r.id))return ok(i,'Już zaakceptowano.');await i.member.roles.add(r);return ok(i,`Nadano ${r}.`)}if(i.customId.startsWith('sg:'))return vote(i);if(i.customId==='ticket:close')return ticketAct(i);if(i.customId==='recruit:apply')return applyRec(i);if(i.customId.startsWith('recruit:accept:')||i.customId.startsWith('recruit:reject:'))return reviewRec(i)}}catch(e){console.error('Interaction',e);if(!i.isRepliable())return;const p={embeds:[emb('❌ Błąd',cut(e.message||'Nieznany błąd.',1500),0xED4245)],flags:MessageFlags.Ephemeral};i.replied||i.deferred?await i.followUp(p).catch(()=>{}):await i.reply(p).catch(()=>{})}});

// ===== EVENTS =====
client.on('guildMemberAdd',m=>{greet(m,'welcome').catch(console.error);log(m.guild,'members',emb('📥 Nowy członek',`${m.user} dołączył.`,0x57F287))});client.on('guildMemberRemove',m=>{greet(m,'goodbye').catch(console.error);log(m.guild,'members',emb('📤 Opuścił serwer',m.user.tag,0xED4245))});client.on('voiceStateUpdate',(a,b)=>voice(a,b).catch(console.error));
client.on('messageCreate',async m=>{if(!m.guild||m.author.bot)return;try{if(await automod(m))return;const c=db('lvl-config');if(!c.enabled)return;const d=xp(m.guild.id,m.author.id),now=Date.now();if(now-(d.lastXp||0)<c.cooldown)return;d.lastXp=now;const gain=c.minXp+Math.floor(Math.random()*(c.maxXp-c.minXp+1));d.xp+=gain;d.totalXp=(d.totalXp||0)+gain;let up=false;while(d.xp>=need(d.level)){d.xp-=need(d.level);d.level++;up=true}save('lvl');if(up){const t=m.guild.channels.cache.get(c.announceChannelId)||m.channel;await t.send({embeds:[emb('🎉 Nowy poziom!',`${m.author} osiągnął **${d.level} poziom**!`,0x57F287)]}).catch(()=>{})}}catch(e){console.error(e)}});
client.on('messageDelete',m=>{if(m.guild&&!m.author?.bot)log(m.guild,'messages',emb('🗑️ Usunięto wiadomość',`Autor: ${m.author||'Nieznany'}\nKanał: ${m.channel}\n${cut(m.content||'Brak',1000)}`,0xED4245))});client.on('messageUpdate',(a,b)=>{if(b.guild&&!b.author?.bot&&a.content!==b.content)log(b.guild,'messages',emb('✏️ Edytowano wiadomość',`Autor: ${b.author}\nPrzed: ${cut(a.content||'Brak',400)}\nPo: ${cut(b.content||'Brak',400)}`,0xFEE75C))});client.on('channelCreate',c=>c.guild&&log(c.guild,'channels',emb('➕ Utworzono kanał',c.name,0x57F287)));client.on('channelDelete',c=>c.guild&&log(c.guild,'channels',emb('➖ Usunięto kanał',c.name,0xED4245)));client.on('roleCreate',r=>log(r.guild,'roles',emb('➕ Utworzono rolę',r.name,0x57F287)));client.on('roleDelete',r=>log(r.guild,'roles',emb('➖ Usunięto rolę',r.name,0xED4245)));

// ===== DEPLOY / TEMPBAN / READY =====
async function deploy(){if(!DEPLOY_COMMANDS){console.log('ℹ️ DEPLOY_COMMANDS=false');return}if(!CLIENT_ID||!GUILD_ID){console.error('Brak CLIENT_ID/GUILD_ID');return}const rest=new REST({version:'10'}).setToken(TOKEN),route=Routes.applicationGuildCommands(CLIENT_ID,GUILD_ID),existing=await rest.get(route),map=new Map(existing.map(x=>[x.name,x]));let u=0,n=0;for(const c of commands){const old=map.get(c.name);try{if(old){await rest.patch(Routes.applicationGuildCommand(CLIENT_ID,GUILD_ID,old.id),{body:c});u++;console.log(`🔄 /${c.name}`)}else{await rest.post(route,{body:c});n++;console.log(`➕ /${c.name}`)}}catch(e){const code=e?.code??e?.rawError?.code;if(code===30034){console.error('⛔ Limit 30034');break}console.error(`❌ /${c.name}`,e)}}console.log(`Komendy: zaktualizowano ${u}, dodano ${n}. Nic nie usunięto.`)}
async function expire(){const now=Date.now(),d=db('kary');let changed=false;for(const[k,e]of Object.entries(d)){if(!Array.isArray(e))continue;const[g,u]=k.split(':'),guild=client.guilds.cache.get(g);if(!guild)continue;for(const x of e)if(x.type==='tempban'&&x.active!==false&&x.expiresAt&&x.expiresAt<=now){await guild.members.unban(u,'TempBan wygasł').catch(()=>{});x.active=false;changed=true}}if(changed)save('kary')}
client.once('clientReady',async r=>{startPanel({client,db,save,commands,BOT_VERSION});console.log(`✅ Bot: ${r.user.tag}`);console.log(`📦 Komendy lokalne: ${commands.length}`);console.log(`🌐 Serwery: ${client.guilds.cache.size}`);console.log(`🚀 DEPLOY_COMMANDS: ${DEPLOY_COMMANDS}`);for(const n of Object.keys(defaults))db(n);migrateStatusPanel();applyStatus();writePanelState();await deploy().catch(console.error);await expire().catch(console.error);for(const g of client.guilds.cache.values()){const rc=db('radio-config');if(rc.enabled&&rc.channelId)await startRadio(g,rc.station,true).catch(e=>console.error('Radio autostart:',e.message))}setInterval(()=>expire().catch(console.error),60000).unref();setInterval(()=>writePanelState(),60000).unref();setInterval(async()=>{for(const g of client.guilds.cache.values())await refreshStatus(g).catch(()=>{})},60000).unref();setInterval(async()=>{for(const g of client.guilds.cache.values()){const rc=db('radio-config'),rr=radioRuntime.get(g.id);if(rc.enabled&&rc.channelId&&!rr?.running)await startRadio(g,rc.station,true).catch(e=>console.error('Radio watchdog:',e.message))}},30000).unref();console.log('✅ TempBan Manager uruchomiony');console.log('✅ Status Panel Auto Refresh uruchomiony');console.log('✅ Radio 24/7 Manager uruchomiony')});
client.on('error',console.error);process.on('unhandledRejection',console.error);process.on('uncaughtException',console.error);client.login(TOKEN);